import{_ as i,a0 as o,w as d,s as r,ao as l,I as p,x as a,a1 as e,A as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const f=JSON.parse('{"title":"/dev/[u]random：對熵的解釋 | LCTT x X-CMD","titleTemplate":false,"description":"/dev/[u]random：對熵的解釋 | LCTT (201805) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"/dev/[u]random：對熵的解釋 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"/dev/[u]random：對熵的解釋 | LCTT (201805) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201805/20171101 -dev-urandom- entropy explained","title":"/dev/[u]random：對熵的解釋","tag":"201805","desc":""},"relativePath":"201805/20171101 -dev-urandom- entropy explained.md","filePath":"[post].md"}'),g={name:"201805/20171101 -dev-urandom- entropy explained.md"};function h(m,s,u,c,v,b){const n=o("Link");return d(),r("div",null,[s[19]||(s[19]=l(`<h1 id="dev-u-random-對熵的解釋" tabindex="-1">/dev/[u]random：對熵的解釋 <a class="header-anchor" href="#dev-u-random-對熵的解釋" aria-label="Permalink to “/dev/[u]random：對熵的解釋”">​</a></h1><h3 id="熵" tabindex="-1">熵 <a class="header-anchor" href="#熵" aria-label="Permalink to “熵”">​</a></h3><p>當談到 <code>/dev/random</code> 和 <code>/dev/urandom</code> 的主題時，你總是會聽到這個詞：“<ruby>熵<rt>Entropy</rt></ruby>”。每個人對此似乎都有自己的比喻。那為我呢？我喜歡將熵視為“隨機果汁”。它是果汁，隨機數需要它變得更隨機。</p><p>如果你曾經生成過 SSL 證書或 GPG 密鑰，那麼可能已經看到過像下面這樣的內容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>We need to generate a lot of random bytes. It is a good idea to perform</span></span>
<span class="line"><span>some other action (type on the keyboard, move the mouse, utilize the</span></span>
<span class="line"><span>disks) during the prime generation; this gives the random number</span></span>
<span class="line"><span>generator a better chance to gain enough entropy.</span></span>
<span class="line"><span>++++++++++..+++++.+++++++++++++++.++++++++++...+++++++++++++++...++++++</span></span>
<span class="line"><span>+++++++++++++++++++++++++++++.+++++..+++++.+++++.+++++++++++++++++++++++++&gt;.</span></span>
<span class="line"><span>++++++++++&gt;+++++...........................................................+++++</span></span>
<span class="line"><span>Not enough random bytes available. Please do some other work to give</span></span>
<span class="line"><span>the OS a chance to collect more entropy! (Need 290 more bytes)</span></span></code></pre></div><p>通過在鍵盤上打字並移動鼠標，你可以幫助生成熵或隨機果汁。</p><p>你可能會問自己……為什麼我需要熵？以及為什麼它對於隨機數真的變得隨機如此重要？那麼，假設我們的熵的來源僅限於鍵盤、鼠標和磁盤 IO 的數據。但是我們的系統是一個服務器，所以我知道沒有鼠標和鍵盤輸入。這意味着唯一的因素是你的 IO。如果它是一個單獨的、幾乎不使用的磁盤，你將擁有較低的熵。這意味着你的系統隨機的能力很弱。換句話説，我可以玩概率遊戲，並大幅減少破解 ssh 密鑰或者解密你認為是加密會話的時間。</p>`,7)),p("p",null,[s[1]||(s[1]=a("好的，但這是很難實現的對吧？不，實際上並非如此。看看這個 ",-1)),e(n,{href:"http://jhurani.com/linux/2017/11/01/%22https://jblevins.org/log/ssh-vulnkey%22"},{default:t(()=>[...s[0]||(s[0]=[a("Debian OpenSSH 漏洞",-1)])]),_:1}),s[2]||(s[2]=a("。這個特定的問題是由於某人刪除了一些負責添加熵的代碼引起的。有傳言説，他們因為它導致 valgrind 發出警告而刪除了它。然而，在這樣做的時候，隨機數現在少了很多隨機性。事實上，熵少了很多，因此暴力破解變成了一個可行的攻擊向量。",-1))]),s[20]||(s[20]=l(`<p>希望到現在為止，我們理解了熵對安全性的重要性。無論你是否意識到你正在使用它。</p><h3 id="dev-random-和-dev-urandom" tabindex="-1">/dev/random 和 /dev/urandom <a class="header-anchor" href="#dev-random-和-dev-urandom" aria-label="Permalink to “/dev/random 和 /dev/urandom”">​</a></h3><p><code>/dev/urandom</code> 是一個偽隨機數生成器，缺乏熵它也<strong>不會</strong>停止。</p><p><code>/dev/random</code> 是一個真隨機數生成器，它會在缺乏熵的時候停止。</p><p>大多數情況下，如果我們正在處理實際的事情，並且它不包含你的核心信息，那麼 <code>/dev/urandom</code> 是正確的選擇。否則，如果就使用 <code>/dev/random</code>，那麼當系統的熵耗盡時，你的程序就會變得有趣。無論它直接失敗，或只是掛起——直到它獲得足夠的熵，這取決於你編寫的程序。</p><h3 id="檢查熵" tabindex="-1">檢查熵 <a class="header-anchor" href="#檢查熵" aria-label="Permalink to “檢查熵”">​</a></h3><p>那麼，你有多少熵？</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@testbox test]# cat /proc/sys/kernel/random/poolsize</span></span>
<span class="line"><span>4096</span></span>
<span class="line"><span>[root@testbox test]# cat /proc/sys/kernel/random/entropy_avail</span></span>
<span class="line"><span>2975</span></span></code></pre></div><p><code>/proc/sys/kernel/random/poolsize</code>，説明熵池的大小（以位為單位）。例如：在停止抽水之前我們應該儲存多少隨機果汁。<code>/proc/sys/kernel/random/entropy_avail</code> 是當前池中隨機果汁的數量（以位為單位）。</p><h3 id="我們如何影響這個數字" tabindex="-1">我們如何影響這個數字？ <a class="header-anchor" href="#我們如何影響這個數字" aria-label="Permalink to “我們如何影響這個數字？”">​</a></h3><p>這個數字可以像我們使用它一樣耗盡。我可以想出的最簡單的例子是將 <code>/dev/random</code> 定向到 <code>/dev/null</code> 中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@testbox test]# cat /dev/random &gt; /dev/null &amp;</span></span>
<span class="line"><span>[1] 19058</span></span>
<span class="line"><span>[root@testbox test]# cat /proc/sys/kernel/random/entropy_avail</span></span>
<span class="line"><span>0</span></span>
<span class="line"><span>[root@testbox test]# cat /proc/sys/kernel/random/entropy_avail</span></span>
<span class="line"><span>1</span></span></code></pre></div>`,12)),p("p",null,[s[4]||(s[4]=a("影響這個最簡單的方法是運行 ",-1)),e(n,{href:"http://www.issihosts.com/haveged/"},{default:t(()=>[...s[3]||(s[3]=[a("Haveged",-1)])]),_:1}),s[5]||(s[5]=a("。Haveged 是一個守護進程，它使用處理器的“抖動”將熵添加到系統熵池中。安裝和基本設置非常簡單。",-1))]),s[21]||(s[21]=l(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@b08s02ur ~]# systemctl enable haveged</span></span>
<span class="line"><span>Created symlink from /etc/systemd/system/multi-user.target.wants/haveged.service to /usr/lib/systemd/system/haveged.service.</span></span>
<span class="line"><span>[root@b08s02ur ~]# systemctl start haveged</span></span></code></pre></div><p>在流量相對中等的機器上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@testbox ~]# pv /dev/random &gt; /dev/null </span></span>
<span class="line"><span>  40 B 0:00:15 [   0 B/s] [                    &lt;=&gt;                                                                                                                                                      ]</span></span>
<span class="line"><span>  52 B 0:00:23 [   0 B/s] [                           &lt;=&gt;                                                                                                                                               ]</span></span>
<span class="line"><span>  58 B 0:00:25 [5.92 B/s] [                              &lt;=&gt;                                                                                                                                            ]</span></span>
<span class="line"><span>  64 B 0:00:30 [6.03 B/s] [                                  &lt;=&gt;                                                                                                                                        ]</span></span>
<span class="line"><span>^C</span></span>
<span class="line"><span>[root@testbox ~]# systemctl start haveged</span></span>
<span class="line"><span>[root@testbox ~]# pv /dev/random &gt; /dev/null </span></span>
<span class="line"><span>7.12MiB 0:00:05 [1.43MiB/s] [                &lt;=&gt;                                                                                                                                                        ]</span></span>
<span class="line"><span>15.7MiB 0:00:11 [1.44MiB/s] [                                    &lt;=&gt;                                                                                                                                    ]</span></span>
<span class="line"><span>27.2MiB 0:00:19 [1.46MiB/s] [                                                               &lt;=&gt;                                                                                                         ]</span></span>
<span class="line"><span>  43MiB 0:00:30 [1.47MiB/s] [                                                                                                    &lt;=&gt;                                                                    ]</span></span>
<span class="line"><span>^C</span></span></code></pre></div><p>使用 <code>pv</code> 我們可以看到我們通過管道傳遞了多少數據。正如你所看到的，在運行 <code>haveged</code> 之前，我們是 2.1 位/秒（B/s）。而在開始運行 <code>haveged</code> 之後，加入處理器的抖動到我們的熵池中，我們得到大約 1.5MiB/秒。</p><hr>`,5)),p("p",null,[s[7]||(s[7]=a("via: ",-1)),e(n,{href:"http://jhurani.com/linux/2017/11/01/entropy-explained.html"},{default:t(()=>[...s[6]||(s[6]=[a("http://jhurani.com/linux/2017/11/01/entropy-explained.html",-1)])]),_:1})]),p("p",null,[s[11]||(s[11]=a("作者：",-1)),e(n,{href:"https://jblevins.org/log/ssh-vulnkey"},{default:t(()=>[...s[8]||(s[8]=[a("James J",-1)])]),_:1}),s[12]||(s[12]=a(" 譯者：",-1)),e(n,{href:"https://github.com/geekpi"},{default:t(()=>[...s[9]||(s[9]=[a("geekpi",-1)])]),_:1}),s[13]||(s[13]=a(" 校對：",-1)),e(n,{href:"https://github.com/wxy"},{default:t(()=>[...s[10]||(s[10]=[a("wxy",-1)])]),_:1})]),p("p",null,[s[16]||(s[16]=a("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[14]||(s[14]=[a("LCTT",-1)])]),_:1}),s[17]||(s[17]=a(" 原創編譯，",-1)),e(n,{href:"https://linux.cn/"},{default:t(()=>[...s[15]||(s[15]=[a("Linux中國",-1)])]),_:1}),s[18]||(s[18]=a(" 榮譽推出",-1))])])}const x=i(g,[["render",h]]);export{f as __pageData,x as default};
